    this.state = {}
    /** @type{PresenceDiff[]} */
    this.pendingDiffs = []
    /** @type{Channel} */
    this.channel = channel
    /** @type{?number} */
    this.joinRef = null
    /** @type{({ onJoin: PresenceOnJoin; onLeave: PresenceOnLeave; onSync: PresenceOnSync })} */
