export interface IcebergErrorResponse {
  error: {
    message: string
    type: string
    code: number
    stack?: string[]
  }
}

export class IcebergError extends Error {
  readonly status: number
  readonly icebergType?: string
  readonly icebergCode?: number
  readonly details?: unknown
  readonly isCommitStateUnknown: boolean

  constructor(
    message: string,
    opts: {
      status: number
      icebergType?: string
      icebergCode?: number
      details?: unknown
    }
  ) {
    super(message)
    this.name = 'IcebergError'
    this.status = opts.status
    this.icebergType = opts.icebergType
    this.icebergCode = opts.icebergCode
    this.details = opts.details

    // Detect CommitStateUnknownException (500, 502, 504 during table commits)
    this.isCommitStateUnknown =
      opts.icebergType === 'CommitStateUnknownException' ||
      ([500, 502, 504].includes(opts.status) && opts.icebergType?.includes('CommitState') === true)
  }

  /**
   * Returns true if the error is a 404 Not Found error.
   */
  isNotFound(): boolean {
    return this.status === 404
  }

  /**
   * Returns true if the error is a 409 Conflict error.
   */
  isConflict(): boolean {
    return this.status === 409
  }

  /**
   * Returns true if the error is a 419 Authentication Timeout error.
   */
  isAuthenticationTimeout(): boolean {
    return this.status === 419
  }
}
export function buildUrl(
  baseUrl: string,
  path: string,
  query?: Record<string, string | undefined>
): string {
  const url = new URL(path, baseUrl)

  if (query) {
    for (const [key, value] of Object.entries(query)) {
      if (value !== undefined) {
        url.searchParams.set(key, value)
      }
    }
  }

  return url.toString()
}
import { IcebergError, type IcebergErrorResponse } from '../errors/IcebergError'
import { buildUrl } from '../utils/url'
import type { AuthConfig, HttpClient, HttpRequest, HttpResponse } from './types'

async function buildAuthHeaders(auth?: AuthConfig): Promise<Record<string, string>> {
  if (!auth || auth.type === 'none') {
    return {}
  }

  if (auth.type === 'bearer') {
    return { Authorization: `Bearer ${auth.token}` }
  }

  if (auth.type === 'header') {
    return { [auth.name]: auth.value }
  }

  if (auth.type === 'custom') {
    return await auth.getHeaders()
  }

  return {}
}

export function createFetchClient(options: {
  baseUrl: string
  auth?: AuthConfig
  fetchImpl?: typeof fetch
}): HttpClient {
  const fetchFn = options.fetchImpl ?? globalThis.fetch

  return {
    async request<T>({
      method,
      path,
      query,
      body,
      headers,
    }: HttpRequest): Promise<HttpResponse<T>> {
      const url = buildUrl(options.baseUrl, path, query)
      const authHeaders = await buildAuthHeaders(options.auth)

      const res = await fetchFn(url, {
        method,
        headers: {
          ...(body ? { 'Content-Type': 'application/json' } : {}),
          ...authHeaders,
          ...headers,
        },
        body: body ? JSON.stringify(body) : undefined,
      })

      const text = await res.text()
      const isJson = (res.headers.get('content-type') || '').includes('application/json')
      const data = isJson && text ? (JSON.parse(text) as T) : (text as T)

      if (!res.ok) {
        const errBody = isJson ? (data as IcebergErrorResponse) : undefined
        const errorDetail = errBody?.error
        throw new IcebergError(
          errorDetail?.message ?? `Request failed with status ${res.status}`,
          {
            status: res.status,
            icebergType: errorDetail?.type,
            icebergCode: errorDetail?.code,
            details: errBody,
          }
        )
      }

      return { status: res.status, headers: res.headers, data: data as T }
    },
  }
}
