/**
 * Gets the current (active) schema from table metadata.
 *
 * @param metadata - Table metadata containing schemas array and current-schema-id
 * @returns The current table schema, or undefined if not found
 */
export function getCurrentSchema(metadata: TableMetadata): TableSchema | undefined {
  return metadata.schemas.find((s) => s['schema-id'] === metadata['current-schema-id'])
}

type CriticalFlow = "booking" | "email" | "cron" | "auth" | "billing";

import { logError } from "@/lib/logger";
import { sendOpsAlert } from "@/lib/ops-alerting";

function serializeError(error: unknown): Record<string, unknown> {
  if (error instanceof Error) {
    return {
      name: error.name,
      message: error.message,
      stack: error.stack
    };
  }

  return {
    value: String(error)
  };
}

export function reportError(
  flow: CriticalFlow,
  event: string,
  error: unknown,
  context?: Record<string, unknown>
): void {
  const payload = {
    level: "error",
    flow,
    event,
    context: context ?? {},
    error: serializeError(error),
    timestamp: new Date().toISOString()
  };

  logError("[observability] reportError", error, {
    flow,
    event,
    requestId: typeof context?.requestId === "string" ? context.requestId : undefined
  });

  void sendOpsAlert({
    flow,
    event,
    context: payload.context,
    error: payload.error,
    timestamp: payload.timestamp
  });

  // Forward to Sentry when configured (non-blocking)
  if (process.env.SENTRY_DSN) {
    void import("@sentry/nextjs")
      .then(({ withScope, captureException }) => {
        withScope((scope) => {
          scope.setTag("flow", flow);
          scope.setTag("event", event);
          scope.setExtras(context ?? {});
          captureException(error instanceof Error ? error : new Error(String(error)));
        });
      })
      .catch(() => {
        // Sentry unavailable — already logged to console above
      });
  }
}

/**
 * Structured JSON logger — single file, no dependencies, no Sentry.
 * All logs output as JSON to console for easy aggregation in production.
 *
 * Sentry error capture remains in observability.ts reportError().
 */

import { randomUUID } from 'crypto';

export interface LogEntry {
  timestamp: string;
  level: 'error' | 'warn' | 'info';
  message: string;
  error?: {
    name?: string;
    message?: string;
    code?: string;
    statusCode?: number;
  };
  context?: Record<string, string | number | boolean | null | undefined>;
}

function normalizeError(error: unknown): LogEntry['error'] | undefined {
  if (!error) return undefined;

  if (error instanceof Error) {
    const entry: LogEntry['error'] = {
      name: error.name,
      message: error.message,
    };

    // Include custom fields if attached
    if ('code' in error && typeof error.code === 'string') {
      entry.code = error.code;
    }
    if ('statusCode' in error && typeof error.statusCode === 'number') {
      entry.statusCode = error.statusCode;
    }

    return entry;
  }

  return { message: String(error) };
}

/**
 * Internal function: output a log entry.
 * Uses console.error for all levels so they're visible in production logs.
 */
function output(entry: LogEntry): void {
  console.error(JSON.stringify(entry));
}

/**
 * Log an error with optional error object and context.
 */
export function logError(
  message: string,
  error?: unknown,
  context?: Record<string, string | number | boolean | null | undefined>
): void {
  output({
    timestamp: new Date().toISOString(),
    level: 'error',
    message,
    error: normalizeError(error),
    context,
  });
}

/**
 * Log a warning (e.g., rate limit exceeded, client blocked).
 * Error object is optional.
 */
export function logWarn(
  message: string,
  context?: Record<string, string | number | boolean | null | undefined>,
  error?: unknown
): void {
  output({
    timestamp: new Date().toISOString(),
    level: 'warn',
    message,
    error: error ? normalizeError(error) : undefined,
    context,
  });
}

/**
 * Log informational message.
 */
export function logInfo(
  message: string,
  context?: Record<string, string | number | boolean | null | undefined>
): void {
  output({
    timestamp: new Date().toISOString(),
    level: 'info',
    message,
    context,
  });
}

/**
 * Extract request ID from headers, or generate a new one.
 * Simple helper, no async context needed.
 */
export function getRequestId(headers: Headers): string {
  return (
    headers.get('x-request-id')?.trim() ||
    headers.get('x-correlation-id')?.trim() ||
    randomUUID()
  );
}

type OpsAlertPayload = {
  flow: "booking" | "email" | "cron" | "auth" | "billing";
  event: string;
  context: Record<string, unknown>;
  error: Record<string, unknown>;
  timestamp: string;
};

let lastSentAt = 0;

export async function sendOpsAlert(payload: OpsAlertPayload): Promise<void> {
  const url = process.env.ALERT_WEBHOOK_URL?.trim();
  if (!url) {
    return;
  }

  const cooldownMs = Number(process.env.ALERT_COOLDOWN_MS ?? "300000");
  if (Number.isFinite(cooldownMs) && cooldownMs > 0) {
    const now = Date.now();
    if (now - lastSentAt < cooldownMs) {
      return;
    }
    lastSentAt = now;
  }

  const bearer = process.env.ALERT_WEBHOOK_BEARER_TOKEN?.trim();

  await fetch(url, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      ...(bearer ? { Authorization: `Bearer ${bearer}` } : {})
    },
    body: JSON.stringify(payload)
  }).catch(() => {
    // Best-effort alerting only.
  });
}
